args.sparql:
SELECT ?film ?label WHERE {
  ?film a dbo:Film .
  ?film rdfs:label ?label .
  FILTER (langMatches(lang(?label), "EN"))
  FILTER (regex(str(?label), "Mumm?y", "i") && regex(str(?label), "Boy", "i"))
} LIMIT 50

SELECT ?film ?filmLabel ?director ?directorLabel ?birthDate WHERE {
  VALUES ?film { dbr:Love_in_a_Fallen_City_(film) dbr:Mummy's_Boys }
  ?film dbo:director ?director .
  OPTIONAL { ?director dbo:birthDate ?bd1 }
  OPTIONAL { ?director dbp:birth_date ?bd2 }
  BIND(coalesce(?bd1, ?bd2) AS ?birthDate)
  ?film rdfs:label ?filmLabel . FILTER(langMatches(lang(?filmLabel), "EN"))
  ?director rdfs:label ?directorLabel . FILTER(langMatches(lang(?directorLabel), "EN"))
}

